def assert_reproduces(name: str, computed: float, published: float, atol: float = 1e-3) -> None:
    """Published values. This cell fails if any of them moves, so a change to
    the analysis cannot silently invalidate the manuscript. `atol=1e-3`
    because the published values are stated to three decimal places, not at
    full float precision.
    """
    if not np.isclose(computed, published, atol=atol, rtol=0):
        raise AssertionError(
            f"{name}: computed {computed!r} does not match the published value "
            f"{published!r} (atol={atol})"
        )


