def build_base_api_frame(d6: pd.DataFrame, d1: pd.DataFrame) -> pd.DataFrame:
    """The API analysis frame: base variant (implicit), all 6 models, built
    identically to the local-path frame (same reference, same bin
    convention) so the two pathways are compared on frames that differ only
    in the serving stack, never in how they were constructed.
    """
    df = d6.merge(
        d1[["image", "reference", "campaign"]],
        on="image", how="inner", validate="many_to_one",
    )
    if len(df) != len(d6):
        raise AssertionError(f"D6 -> D1 join dropped rows: {len(d6)} in, {len(df)} out")
    df["e"] = df["vegetation_percent"] - df["reference"]
    df["abs_e"] = df["e"].abs()
    df["bin"] = co.assign_bins(df["reference"])
    return df


