# %% [markdown]
# ## Analysis
#
# **Why the API path gets the same treatment the local path gets.** Agreement
# quantities alone -- exact-agreement rate, median absolute difference,
# limits of agreement, rank correlation -- do not touch the reference and
# cannot say whether a model is *more accurate* through one path than the
# other. Computing overall MAE, balanced MAE, their bootstrap
# intervals and a paired Wilcoxon on the API side, exactly as Q1 computes them
# on the local side, is not done so the API numbers can be reported as a
# result -- it is done so the comparison between the two paths is a fair one,
# built from the same statistics on both sides.
#
# **Overall MAE and balanced MAE are read the same way here as everywhere
# else in this study.** Overall MAE carries the one test -- the paired
# two-sided Wilcoxon signed-rank on per-image absolute error -- corrected
# with Holm-Bonferroni across the six models (first threshold 0.05/6 =
# 0.00833). Balanced MAE is never compared by a p-value: its local-minus-API
# difference is a BCa interval, uncorrected, read one at a time. The 24 model
# x prompt configuration rows carry neither correction: they are descriptive,
# with intervals.

# %%
FAMILY_SIZE_Q7 = 6
HOLM_ALPHA = 0.05
holm_threshold_q7 = co.holm_first_threshold(HOLM_ALPHA, FAMILY_SIZE_Q7)
print(f"Holm-Bonferroni across the six per-model Wilcoxon tests, first threshold = "
      f"{HOLM_ALPHA}/{FAMILY_SIZE_Q7} = {holm_threshold_q7:.5f}.")


def level_metrics(frame: pd.DataFrame, group_cols: list) -> dict:
    """Overall MAE and balanced MAE for one (model[, prompt]) group on one
    pathway, pooling per-image mean absolute error over any axis not in
    `group_cols` -- the per-image value is the mean of the absolute error,
    never the absolute error of the mean prediction, so pooling never
    behaves like an ensemble.
    """
    out = {}
    for keys, g in frame.groupby(group_cols):
        keys = keys if isinstance(keys, tuple) else (keys,)
        per_image = g.groupby("image").agg(abs_e=("abs_e", "mean"), bin=("bin", "first"))
        bal = co.balanced_mae(per_image["abs_e"], per_image["bin"])
        out[keys] = {
            "overall_mae": float(per_image["abs_e"].mean()),
            "balanced_mae": bal.balanced_mae,
            "per_image": per_image,
        }
    return out


local_by_combo = level_metrics(base_local, ["model", "prompt"])
api_by_combo = level_metrics(base_api, ["model", "prompt"])
local_by_model = level_metrics(base_local, ["model"])
api_by_model = level_metrics(base_api, ["model"])

print(f"Configurations (24): local computed for {len(local_by_combo)}, API for {len(api_by_combo)}")
print(f"Models (6): local computed for {len(local_by_model)}, API for {len(api_by_model)}")

# %% [markdown]
# **A performance note that changes no statistic.** This notebook needs many
# more image bootstraps than most -- four level intervals and two difference
# intervals per configuration, the same six per model, plus one per reversed
# pair -- and the shared bootstrap routine's per-replicate statistic rebuilds
# a `pandas` frame and regroups it on every one of tens of thousands of
# resamples, which is correct but needlessly slow at this call volume. The
# functions below replace only the *inside* of that statistic -- reducing a
# bin-mean or a balanced-MAE evaluation to plain array lookups on a resample
# that the same resampling and pairing logic still produces. Every number
# this produces is checked against the shared, slower implementation once
# below, so the speed-up is verified to compute the identical quantity, not
# merely a faster-looking one.

# %%
_BIN_CODE_MAP = {label: i for i, label in enumerate(co.BIN_LABELS)}


def _fast_overall_mean(abs_e: np.ndarray) -> float:
    return float(abs_e.mean())


def _fast_balanced_mae(abs_e: np.ndarray, bin_codes: np.ndarray) -> float:
    """Numerically identical to the shared balanced-MAE function -- the
    unweighted mean of the five per-bin means -- computed with `np.add.at`
    instead of a `groupby`, so the same quantity is reached without rebuilding
    a `pandas` frame on every bootstrap replicate.
    """
    sums = np.zeros(5)
    counts = np.zeros(5)
    np.add.at(sums, bin_codes, abs_e)
    np.add.at(counts, bin_codes, 1)
    with np.errstate(invalid="ignore"):
        per_bin = sums / counts
    return float(np.nanmean(per_bin))


def make_per_image_arrays(per_image: pd.DataFrame) -> dict:
    """Precompute the numpy arrays a fast statistic needs from a per-image
    frame (index = image, columns abs_e/bin), once per configuration/model
    rather than once per bootstrap replicate.
    """
    frame = per_image.reset_index()
    return {
        "image": frame["image"].values,
        "abs_e": frame["abs_e"].values,
        "bin_code": frame["bin"].map(_BIN_CODE_MAP).values,
    }


def fast_image_bootstrap(per_image: pd.DataFrame, stat: str, rng: np.random.Generator,
                          B: int = co.B_BOOTSTRAP) -> "co.BootstrapResult":
    """The image bootstrap -- resample images with replacement, recompute the
    statistic on each resample, take a BCa interval with a fallback to the
    plain percentile interval where BCa's bias-correction or acceleration is
    undefined -- with the same draw sequence and the same fallback rule as
    the shared implementation, but evaluating `stat` from precomputed numpy
    arrays instead of rebuilding a `pandas` frame and regrouping it on every
    replicate. `stat` is `'overall_mae'` or `'balanced_mae'`, evaluated on
    one pathway's own per-image frame.
    """
    arrays = make_per_image_arrays(per_image)
    images_all = arrays["image"]
    abs_e_all = arrays["abs_e"]
    bin_all = arrays["bin_code"]
    pos_by_image = {img: i for i, img in enumerate(images_all)}
    n = len(images_all)

    def statistic_on_positions(positions: np.ndarray) -> float:
        a = abs_e_all[positions]
        if stat == "overall_mae":
            return _fast_overall_mean(a)
        return _fast_balanced_mae(a, bin_all[positions])

    theta_hat = statistic_on_positions(np.arange(n))

    boot_vals = np.empty(B)
    n_violations = 0
    idx_array = np.arange(n)
    for i in range(B):
        drawn = rng.choice(idx_array, size=n, replace=True)
        present_bins = set(bin_all[drawn])
        if len(present_bins) < 5:
            n_violations += 1
        boot_vals[i] = statistic_on_positions(drawn)

    jack_vals = np.empty(n)
    full_mask = np.ones(n, dtype=bool)
    for i in range(n):
        full_mask[i] = False
        jack_vals[i] = statistic_on_positions(idx_array[full_mask])
        full_mask[i] = True

    lo = np.percentile(boot_vals, 2.5)
    hi = np.percentile(boot_vals, 97.5)
    ci_method = "percentile (BCa fallback)"
    bca_lo, bca_hi, used_bca = co._bca_interval(theta_hat, boot_vals, jack_vals, alpha=0.05)
    if used_bca:
        lo, hi, ci_method = bca_lo, bca_hi, "BCa"

    return co.BootstrapResult(
        estimate=theta_hat, ci_lo=lo, ci_hi=hi, ci_method=ci_method,
        boot_values=boot_vals, n_empty_bin_violations=n_violations, p_two_sided=None,
    )


def fast_paired_diff_bootstrap(per_image_local: pd.DataFrame, per_image_api: pd.DataFrame,
                                stat: str, rng: np.random.Generator,
                                B: int = co.B_BOOTSTRAP) -> "co.BootstrapResult":
    """The local-minus-API difference of one metric, bootstrapped by
    resampling images once per replicate and evaluating both sides on the
    same drawn image set, so a resample never scores one path on one set of
    images and the other path on a different set. Verified against the
    shared, slower implementation below.
    """
    merged = per_image_local.reset_index().merge(
        per_image_api.reset_index(), on="image", suffixes=("_local", "_api"),
    )
    images_all = merged["image"].values
    abs_e_local = merged["abs_e_local"].values
    abs_e_api = merged["abs_e_api"].values
    bin_local = merged["bin_local"].map(_BIN_CODE_MAP).values
    bin_api = merged["bin_api"].map(_BIN_CODE_MAP).values
    n = len(images_all)

    def statistic_on_positions(positions: np.ndarray) -> float:
        if stat == "overall_mae":
            return _fast_overall_mean(abs_e_local[positions]) - _fast_overall_mean(abs_e_api[positions])
        bal_l = _fast_balanced_mae(abs_e_local[positions], bin_local[positions])
        bal_a = _fast_balanced_mae(abs_e_api[positions], bin_api[positions])
        return bal_l - bal_a

    theta_hat = statistic_on_positions(np.arange(n))
    idx_array = np.arange(n)

    boot_vals = np.empty(B)
    n_violations = 0
    for i in range(B):
        drawn = rng.choice(idx_array, size=n, replace=True)
        present_bins = set(bin_local[drawn])
        if len(present_bins) < 5:
            n_violations += 1
        boot_vals[i] = statistic_on_positions(drawn)

    jack_vals = np.empty(n)
    full_mask = np.ones(n, dtype=bool)
    for i in range(n):
        full_mask[i] = False
        jack_vals[i] = statistic_on_positions(idx_array[full_mask])
        full_mask[i] = True

    lo = np.percentile(boot_vals, 2.5)
    hi = np.percentile(boot_vals, 97.5)
    ci_method = "percentile (BCa fallback)"
    bca_lo, bca_hi, used_bca = co._bca_interval(theta_hat, boot_vals, jack_vals, alpha=0.05)
    if used_bca:
        lo, hi, ci_method = bca_lo, bca_hi, "BCa"

    return co.BootstrapResult(
        estimate=theta_hat, ci_lo=lo, ci_hi=hi, ci_method=ci_method,
        boot_values=boot_vals, n_empty_bin_violations=n_violations, p_two_sided=None,
    )


# %% [markdown]
# **Verifying the fast path against the shared, slower one.** One
# configuration (the observed-best local configuration) is bootstrapped both
# ways with the same seed, and the point estimates -- which are deterministic
# and must match exactly -- and the interval endpoints -- which must match to
# floating-point tolerance, since both draw from `rng.choice` in the same
# sequence -- are compared before the fast path is trusted for the full table.

# %%
_verify_pi = local_by_combo[("Llama-4-Maverick", "Short")]["per_image"]
_rng_a = np.random.default_rng(999_001)
_rng_b = np.random.default_rng(999_001)
_slow = co.image_bootstrap(
    _verify_pi.reset_index(), lambda f: co.balanced_mae(f["abs_e"], f["bin"]).balanced_mae,
    _rng_a, image_col="image", bin_col="bin", B=2_000,
)
_fast = fast_image_bootstrap(_verify_pi, "balanced_mae", _rng_b, B=2_000)
assert np.isclose(_slow.estimate, _fast.estimate, atol=1e-9), "fast-path point estimate diverged from the shared implementation"
assert np.isclose(_slow.ci_lo, _fast.ci_lo, atol=1e-6) and np.isclose(_slow.ci_hi, _fast.ci_hi, atol=1e-6), (
    "fast-path interval diverged from the shared implementation under an identical draw sequence"
)
print(f"Fast-path verification passed: balanced MAE = {_fast.estimate:.4f} "
      f"[{_fast.ci_lo:.4f}, {_fast.ci_hi:.4f}] on both implementations (B=2,000 check run).")

# The paired-difference fast path is checked the same way, on the same
# configuration against its API counterpart, so the difference statistic --
# not only the single-pathway statistic above -- is confirmed identical to
# the shared implementation before it is trusted for every configuration,
# model and reversal-pair row below.
_verify_pi_api = api_by_combo[("Llama-4-Maverick", "Short")]["per_image"]
_rng_c = np.random.default_rng(999_002)
_rng_d = np.random.default_rng(999_002)


def _slow_diff_stat(f):
    bal_l = co.balanced_mae(f["abs_e_local"], f["bin_local"]).balanced_mae
    bal_a = co.balanced_mae(f["abs_e_api"], f["bin_api"]).balanced_mae
    return bal_l - bal_a


_merged_verify = _verify_pi.reset_index().merge(
    _verify_pi_api.reset_index(), on="image", suffixes=("_local", "_api"),
)
_slow_diff = co.image_bootstrap(
    _merged_verify, _slow_diff_stat, _rng_c, image_col="image", bin_col="bin_local", B=2_000,
)
_fast_diff = fast_paired_diff_bootstrap(_verify_pi, _verify_pi_api, "balanced_mae", _rng_d, B=2_000)
assert np.isclose(_slow_diff.estimate, _fast_diff.estimate, atol=1e-9), (
    "fast-path paired-difference point estimate diverged from the shared implementation"
)
assert np.isclose(_slow_diff.ci_lo, _fast_diff.ci_lo, atol=1e-6) and np.isclose(_slow_diff.ci_hi, _fast_diff.ci_hi, atol=1e-6), (
    "fast-path paired-difference interval diverged from the shared implementation under an identical draw sequence"
)
print(f"Fast-path paired-difference verification passed: local-minus-API balanced MAE = "
      f"{_fast_diff.estimate:.4f} [{_fast_diff.ci_lo:.4f}, {_fast_diff.ci_hi:.4f}] on both "
      f"implementations (B=2,000 check run).")

# %% [markdown]
# ### Per-configuration table (24 rows) — descriptive, intervals, no correction
#
# Both metrics on both paths, the paired local-minus-API difference on each
# with a BCa interval, the rank on each path by balanced MAE, and the rank
# change. No p-value anywhere in this table: with 24 configurations and no
# pre-specified pairing between them, a p-value here would need its own
# multiple-comparison correction that this table does not attempt, so the
# comparison stays a magnitude with an interval.

# %%
combo_rows = []
for (model, prompt), loc in local_by_combo.items():
    api = api_by_combo[(model, prompt)]

    mae_o_ci = fast_image_bootstrap(loc["per_image"], "overall_mae", rng_level_ci)
    mae_b_ci = fast_image_bootstrap(loc["per_image"], "balanced_mae", rng_level_ci)
    mae_o_ci_api = fast_image_bootstrap(api["per_image"], "overall_mae", rng_level_ci)
    mae_b_ci_api = fast_image_bootstrap(api["per_image"], "balanced_mae", rng_level_ci)

    diff_o = fast_paired_diff_bootstrap(loc["per_image"], api["per_image"], "overall_mae", rng_diff_ci)
    diff_b = fast_paired_diff_bootstrap(loc["per_image"], api["per_image"], "balanced_mae", rng_diff_ci)

    # Llama-4-Maverick's run-to-run reproducibility floor is measured on the
    # overall-MAE scale (the 100-image determinism subsample has too few
    # high-cover images to support a bin-weighted floor). Any directional
    # claim about Maverick's balanced MAE therefore carries a flag saying so,
    # rather than a floor comparison this data cannot support.
    if model == "Llama-4-Maverick":
        floor_branch = co.maverick_balanced_mae_claim_branch(maverick_floor.delta_mav)
    else:
        floor_branch = {"floor_not_estimable_for_balanced_mae": False, "maverick_floor_delta": np.nan, "caveat": ""}

    combo_rows.append({
        "question_id": "Q7", "model": model, "prompt": prompt,
        "overall_mae_local": loc["overall_mae"], "overall_mae_local_ci_lo": mae_o_ci.ci_lo,
        "overall_mae_local_ci_hi": mae_o_ci.ci_hi,
        "overall_mae_api": api["overall_mae"], "overall_mae_api_ci_lo": mae_o_ci_api.ci_lo,
        "overall_mae_api_ci_hi": mae_o_ci_api.ci_hi,
        "overall_mae_diff_local_minus_api": diff_o.estimate,
        "overall_mae_diff_ci_lo": diff_o.ci_lo, "overall_mae_diff_ci_hi": diff_o.ci_hi,
        "overall_mae_diff_ci_method": diff_o.ci_method,
        "balanced_mae_local": loc["balanced_mae"], "balanced_mae_local_ci_lo": mae_b_ci.ci_lo,
        "balanced_mae_local_ci_hi": mae_b_ci.ci_hi,
        "balanced_mae_api": api["balanced_mae"], "balanced_mae_api_ci_lo": mae_b_ci_api.ci_lo,
        "balanced_mae_api_ci_hi": mae_b_ci_api.ci_hi,
        "balanced_mae_diff_local_minus_api": diff_b.estimate,
        "balanced_mae_diff_ci_lo": diff_b.ci_lo, "balanced_mae_diff_ci_hi": diff_b.ci_hi,
        "balanced_mae_diff_ci_method": diff_b.ci_method,
        "balanced_mae_interval_uncorrected": True,
        "floor_not_estimable_for_balanced_mae": floor_branch["floor_not_estimable_for_balanced_mae"],
        "maverick_floor_delta": floor_branch["maverick_floor_delta"],
        "caveat": floor_branch["caveat"],
        "tier": "secondary", "corrected": False, "claim_wording": "stack and possibly weights",
    })

pathway_by_configuration = pd.DataFrame(combo_rows)

# Rank on each path by balanced MAE (lower = better = rank 1), and the change.
pathway_by_configuration["rank_local"] = pathway_by_configuration["balanced_mae_local"].rank(method="min").astype(int)
pathway_by_configuration["rank_api"] = pathway_by_configuration["balanced_mae_api"].rank(method="min").astype(int)
pathway_by_configuration["rank_change_local_minus_api"] = (
    pathway_by_configuration["rank_local"] - pathway_by_configuration["rank_api"]
)
pathway_by_configuration = pathway_by_configuration.sort_values("balanced_mae_local").reset_index(drop=True)

print(f"Per-configuration table: {len(pathway_by_configuration)} rows (expected 24)")
pathway_by_configuration[[
    "model", "prompt", "overall_mae_local", "overall_mae_api", "balanced_mae_local",
    "balanced_mae_api", "rank_local", "rank_api", "rank_change_local_minus_api",
]]

