# %% [markdown]
# ### Per-model table (6 rows) — the Holm-corrected Wilcoxon
#
# The same metrics, pooled over the four prompts, plus the one test in this
# notebook: a paired two-sided Wilcoxon signed-rank on per-image absolute
# error, local minus API, corrected with Holm-Bonferroni across the six
# models. Companion effect sizes (Hodges-Lehmann median difference,
# matched-pairs rank-biserial correlation, win rate) travel with every row.
# The Llama-4-Maverick row additionally carries the reproducibility floor on
# the overall-MAE scale -- exactly the scale the Wilcoxon runs on and exactly
# the scale the floor was measured on.

# %%
model_rows = []
raw_p = []
per_model_results = {}

for model in co.MODELS:
    loc = local_by_model[(model,)]
    api = api_by_model[(model,)]

    merged = loc["per_image"].reset_index().merge(
        api["per_image"].reset_index(), on="image", suffixes=("_local", "_api"),
    )
    assert len(merged) == 1155, f"{model}: expected 1,155 paired images, got {len(merged)}"

    x = merged["abs_e_local"].values  # local |e|, per image
    y = merged["abs_e_api"].values    # API |e|, per image
    diff = x - y                      # positive => local had the larger |e| (API more accurate)

    wil = co.paired_wilcoxon(x, y)
    hl = co.hodges_lehmann(diff)
    rb = co.rank_biserial_matched_pairs(diff)
    wr = co.win_rate(x, y)  # "win" = local has the smaller |e|

    mae_o_ci = fast_image_bootstrap(loc["per_image"], "overall_mae", rng_level_ci)
    mae_b_ci = fast_image_bootstrap(loc["per_image"], "balanced_mae", rng_level_ci)
    mae_o_ci_api = fast_image_bootstrap(api["per_image"], "overall_mae", rng_level_ci)
    mae_b_ci_api = fast_image_bootstrap(api["per_image"], "balanced_mae", rng_level_ci)

    diff_o = fast_paired_diff_bootstrap(loc["per_image"], api["per_image"], "overall_mae", rng_diff_ci)
    diff_b = fast_paired_diff_bootstrap(loc["per_image"], api["per_image"], "balanced_mae", rng_diff_ci)

    is_maverick = model == "Llama-4-Maverick"
    within_floor = co.maverick_within_floor(diff_o.estimate, maverick_floor.delta_mav) if is_maverick else None

    # Llama-4-Maverick's balanced-MAE difference has no equivalent floor to
    # be read against -- the floor is only ever measured on the overall-MAE
    # scale -- so its balanced-MAE row is flagged rather than given a
    # within/above-floor verdict it cannot support.
    if is_maverick:
        floor_branch = co.maverick_balanced_mae_claim_branch(maverick_floor.delta_mav)
    else:
        floor_branch = {"floor_not_estimable_for_balanced_mae": False, "caveat": ""}

    row = {
        "question_id": "Q7", "model": model, "n": int(len(merged)),
        "overall_mae_local": loc["overall_mae"], "overall_mae_local_ci_lo": mae_o_ci.ci_lo,
        "overall_mae_local_ci_hi": mae_o_ci.ci_hi,
        "overall_mae_api": api["overall_mae"], "overall_mae_api_ci_lo": mae_o_ci_api.ci_lo,
        "overall_mae_api_ci_hi": mae_o_ci_api.ci_hi,
        "overall_mae_diff_local_minus_api": diff_o.estimate,
        "overall_mae_diff_ci_lo": diff_o.ci_lo, "overall_mae_diff_ci_hi": diff_o.ci_hi,
        "overall_mae_diff_ci_method": diff_o.ci_method,
        "balanced_mae_local": loc["balanced_mae"], "balanced_mae_local_ci_lo": mae_b_ci.ci_lo,
        "balanced_mae_local_ci_hi": mae_b_ci.ci_hi,
        "balanced_mae_api": api["balanced_mae"], "balanced_mae_api_ci_lo": mae_b_ci_api.ci_lo,
        "balanced_mae_api_ci_hi": mae_b_ci_api.ci_hi,
        "balanced_mae_diff_local_minus_api": diff_b.estimate,
        "balanced_mae_diff_ci_lo": diff_b.ci_lo, "balanced_mae_diff_ci_hi": diff_b.ci_hi,
        "balanced_mae_diff_ci_method": diff_b.ci_method,
        "balanced_mae_interval_uncorrected": True,
        "wilcoxon_statistic": wil.statistic, "p_raw": wil.p_value, "p_holm": np.nan,
        "n_zero_diff": wil.n_zero_diff, "n_tied_ranks": wil.n_tied_ranks,
        "hl_median_diff_local_minus_api": hl, "rank_biserial": rb,
        "win_rate_local": wr["win_rate_a"], "win_rate_api": wr["win_rate_b"], "tie_rate": wr["tie_rate"],
        "c1_serving_confounded": False,
        "c1_note": "both sides are the same model; the comparison crosses stack, not model family.",
        "maverick_floor_delta": maverick_floor.delta_mav if is_maverick else np.nan,
        "within_run_to_run_variability": within_floor,
        "floor_not_estimable_for_balanced_mae": floor_branch["floor_not_estimable_for_balanced_mae"],
        "caveat": floor_branch["caveat"],
        "tier": "secondary", "corrected": True, "claim_wording": "stack and possibly weights",
    }
    model_rows.append(row)
    raw_p.append(wil.p_value)
    per_model_results[model] = {"diff": diff, "x": x, "y": y}

p_holm = co.holm_adjust(raw_p, family="Q7", family_size=FAMILY_SIZE_Q7)
for i, row in enumerate(model_rows):
    row["p_holm"] = float(p_holm[i])

pathway_by_model = pd.DataFrame(model_rows).sort_values("model").reset_index(drop=True)
print(f"Per-model table: {len(pathway_by_model)} rows (expected 6)")
pathway_by_model[[
    "model", "overall_mae_local", "overall_mae_api", "balanced_mae_local", "balanced_mae_api",
    "p_raw", "p_holm", "within_run_to_run_variability",
]]

