# %% [markdown]
# ### Agreement quantities
#
# Exact-agreement rate, median absolute local-minus-API difference, empirical
# 2.5/97.5 percentile limits of agreement (not Bland-Altman's ±1.96 SD limits,
# because K5 above rejects normality of the stack difference for every model),
# tie-corrected Spearman, at both the per-model and per-model x prompt grain.

# %%
agreement_rows = []
for model in co.MODELS:
    loc = base_local[base_local["model"] == model]
    api = base_api[base_api["model"] == model]
    merged = loc.merge(api, on=["image", "prompt"], suffixes=("_local", "_api"), validate="one_to_one")
    assert len(merged) == 4620, f"{model}: expected 4,620 paired rows, got {len(merged)}"

    stack_diff = merged["vegetation_percent_local"] - merged["vegetation_percent_api"]
    exact_agree = float((stack_diff == 0).mean())
    abs_diff = stack_diff.abs()
    median_abs_diff = float(abs_diff.median())
    iqr_lo, iqr_hi = np.percentile(abs_diff, [25, 75])
    loa_lo, loa_hi = np.percentile(stack_diff, [2.5, 97.5])
    rho, rho_p = co.spearman_tie_corrected(
        merged["vegetation_percent_local"].values, merged["vegetation_percent_api"].values,
    )

    agreement_rows.append({
        "question_id": "Q7", "level": "model", "model": model, "prompt": "all (pooled)",
        "n_pairs": int(len(merged)), "exact_agreement_rate": exact_agree,
        "median_abs_diff_local_minus_api": median_abs_diff,
        "abs_diff_iqr_lo": float(iqr_lo), "abs_diff_iqr_hi": float(iqr_hi),
        "empirical_loa_2_5pct": float(loa_lo), "empirical_loa_97_5pct": float(loa_hi),
        "spearman_tie_corrected": rho, "spearman_p": rho_p,
        "tier": "secondary", "corrected": False, "claim_wording": "stack and possibly weights",
    })

for model in co.MODELS:
    for prompt in sorted(base_local["prompt"].unique()):
        loc = base_local[(base_local["model"] == model) & (base_local["prompt"] == prompt)]
        api = base_api[(base_api["model"] == model) & (base_api["prompt"] == prompt)]
        merged = loc.merge(api, on="image", suffixes=("_local", "_api"), validate="one_to_one")
        assert len(merged) == 1155, f"{model}/{prompt}: expected 1,155 paired rows, got {len(merged)}"

        stack_diff = merged["vegetation_percent_local"] - merged["vegetation_percent_api"]
        exact_agree = float((stack_diff == 0).mean())
        abs_diff = stack_diff.abs()
        median_abs_diff = float(abs_diff.median())
        iqr_lo, iqr_hi = np.percentile(abs_diff, [25, 75])
        loa_lo, loa_hi = np.percentile(stack_diff, [2.5, 97.5])
        rho, rho_p = co.spearman_tie_corrected(
            merged["vegetation_percent_local"].values, merged["vegetation_percent_api"].values,
        )

        agreement_rows.append({
            "question_id": "Q7", "level": "model_x_prompt", "model": model, "prompt": prompt,
            "n_pairs": int(len(merged)), "exact_agreement_rate": exact_agree,
            "median_abs_diff_local_minus_api": median_abs_diff,
            "abs_diff_iqr_lo": float(iqr_lo), "abs_diff_iqr_hi": float(iqr_hi),
            "empirical_loa_2_5pct": float(loa_lo), "empirical_loa_97_5pct": float(loa_hi),
            "spearman_tie_corrected": rho, "spearman_p": rho_p,
            "tier": "secondary", "corrected": False, "claim_wording": "stack and possibly weights",
        })

pathway_agreement = pd.DataFrame(agreement_rows)

overall_stack_diff = (base_local.merge(
    base_api, on=["image", "prompt", "model"], suffixes=("_local", "_api"),
))
overall_stack_diff["stack_diff"] = (
    overall_stack_diff["vegetation_percent_local"] - overall_stack_diff["vegetation_percent_api"]
)
overall_exact_agree = float((overall_stack_diff["stack_diff"] == 0).mean())
overall_median_abs_diff = float(overall_stack_diff["stack_diff"].abs().median())

print(f"Exact agreement across all 27,720 matched responses: {overall_exact_agree:.4f} "
      f"({overall_exact_agree * 100:.1f}%)")
print(f"Median |local - api| across all matched responses: {overall_median_abs_diff:.4f} cover points")

assert_reproduces("exact_agreement_rate", overall_exact_agree, 0.496, atol=0.002)
assert_reproduces("median_abs_diff", overall_median_abs_diff, 0.5, atol=0.05)
print("Exact-agreement rate and median absolute difference reproduce the required values: "
      "49.6% and 0.5 cover points.")

pathway_agreement[pathway_agreement["level"] == "model"][
    ["model", "n_pairs", "exact_agreement_rate", "median_abs_diff_local_minus_api",
     "empirical_loa_2_5pct", "empirical_loa_97_5pct", "spearman_tie_corrected"]
]

# %% [markdown]
# ### Kendall tau-b on the 24-configuration balanced-MAE ranking
#
# The practically important form of the agreement question: does the ranking
# by balanced MAE over the 24 model x prompt configurations agree between the
# two paths? No p-value is reported for this rank correlation -- the 24 units
# are not independent exchangeable pairs, they are built from the same 1,155
# images and share models, prompts and reference, so `stats.kendalltau`'s
# asymptotic null does not apply here, exactly as Q1's own respecified
# ranking-agreement construction states.

# %%
tau_combo, tau_combo_p = stats.kendalltau(
    pathway_by_configuration["balanced_mae_local"], pathway_by_configuration["balanced_mae_api"],
)
tau_combo = float(tau_combo)
pct_concordant = (tau_combo + 1) / 2  # tau_b -> share of concordant pairs, ignoring ties
print(f"Kendall tau_b (24-configuration balanced-MAE ranking, local vs API) = {tau_combo:.4f}")
print(f"-> {pct_concordant * 100:.1f}% of configuration pairs ordered alike")

assert_reproduces("kendall_tau_b", tau_combo, 0.746, atol=0.005)
assert_reproduces("pct_concordant", pct_concordant * 100, 87.3, atol=0.2)
print("Kendall tau_b and the derived concordant-pair share reproduce the required values: "
      "0.746 and 87.3%.")

# %% [markdown]
# ## Rank reversals — the rule for what counts
#
# **A reversal counts only if the two configurations were separated on the
# local path.** Two configurations that were never distinguishable did not
# have an order to reverse, so swapping them under the API path is not a
# finding. Operationally: for every pair of configurations whose relative
# order by balanced MAE flips between the two paths, the local-path balanced-
# MAE difference is bootstrapped, and the reversal counts only if that
# interval excludes zero. This is data-driven and needs no chosen threshold,
# which is the reason for preferring it over an arbitrary minimum-gap rule.
#
# **The interval is BCa, exactly as it is everywhere else in this study**
# — never the plain percentile interval, which is not the method
# this plan uses and reads as narrower or wider than BCa on skewed resample
# distributions. `fast_paired_diff_bootstrap` computes both internally and
# reports whichever the shared library's own fallback rule selects: BCa where
# it is defined, the percentile interval only where BCa's bias-correction or
# acceleration is undefined (fewer than 50 distinct bootstrap values, or the
# observed statistic sits exactly at the resample distribution's edge). Which
# method was used for each pair is recorded in `local_gap_ci_method` in
# `Q7_rank_reversals.csv`, so a silent mix of the two is never left invisible.

# %%
combo_keys = list(zip(pathway_by_configuration["model"], pathway_by_configuration["prompt"]))
n_combo = len(combo_keys)
bal_local = dict(zip(combo_keys, pathway_by_configuration["balanced_mae_local"]))
bal_api = dict(zip(combo_keys, pathway_by_configuration["balanced_mae_api"]))

per_image_by_combo = {(m, p): local_by_combo[(m, p)]["per_image"] for (m, p) in combo_keys}

pair_rows = []
n_pairs_total = 0
n_reversed = 0
for i in range(n_combo):
    for j in range(i + 1, n_combo):
        n_pairs_total += 1
        key_a, key_b = combo_keys[i], combo_keys[j]
        order_local = np.sign(bal_local[key_a] - bal_local[key_b])
        order_api = np.sign(bal_api[key_a] - bal_api[key_b])
        if order_local == 0 or order_api == 0:
            reversed_pair = False
        else:
            reversed_pair = order_local != order_api
        if reversed_pair:
            n_reversed += 1
            pi_a = per_image_by_combo[key_a]
            pi_b = per_image_by_combo[key_b]
            boot = fast_paired_diff_bootstrap(pi_a, pi_b, "balanced_mae", rng_reversal)
            separated_locally = bool(boot.ci_lo > 0 or boot.ci_hi < 0)
            pair_rows.append({
                "question_id": "Q7",
                "config_a_model": key_a[0], "config_a_prompt": key_a[1],
                "config_b_model": key_b[0], "config_b_prompt": key_b[1],
                "balanced_mae_local_a": bal_local[key_a], "balanced_mae_local_b": bal_local[key_b],
                "balanced_mae_api_a": bal_api[key_a], "balanced_mae_api_b": bal_api[key_b],
                "local_gap_a_minus_b": boot.estimate,
                "local_gap_ci_lo": boot.ci_lo, "local_gap_ci_hi": boot.ci_hi,
                "local_gap_ci_method": boot.ci_method,
                "separated_locally": separated_locally,
                "counts_as_real_reversal": separated_locally,
                "tier": "secondary", "corrected": False, "claim_wording": "stack and possibly weights",
            })

rank_reversals = pd.DataFrame(pair_rows)
n_real_reversals = int(rank_reversals["counts_as_real_reversal"].sum()) if len(rank_reversals) else 0
n_not_separated = len(rank_reversals) - n_real_reversals

print(f"Total configuration pairs: {n_pairs_total} (expected 276)")
print(f"Reversed pairs: {n_reversed} (expected 35)")
print(f"Real reversals (separated locally): {n_real_reversals} (expected 12); "
      f"not separated: {n_not_separated} (expected 23)")
print("CI method used per reversed pair:")
print(rank_reversals["local_gap_ci_method"].value_counts().to_string())

assert n_pairs_total == 276, f"expected 276 configuration pairs, got {n_pairs_total}"
assert n_reversed == 35, f"expected 35 reversed pairs, got {n_reversed}"
assert n_real_reversals == 12, f"expected 12 real reversals, got {n_real_reversals}"
assert n_not_separated == 23, f"expected 23 pairs that do not count, got {n_not_separated}"
print("Pair counts reproduce the required values: 276 pairs, 35 reversed, "
      "12 separated locally (real reversals), 23 not separated.")

